def find_judge_brute(n, trust):
    for candidate in range(1, n + 1):
        trusts_someone = any(a == candidate for a, b in trust)     # scan once
        trusted_by_count = sum(1 for a, b in trust if b == candidate)  # scan again
        if not trusts_someone and trusted_by_count == n - 1:
            return candidate
    return -1

