def find_judge(n, trust):
    trust_count = [0] * (n + 1)
    trusted_by_count = [0] * (n + 1)
    for a, b in trust:
        trust_count[a] += 1                                    # a trusts someone
        trusted_by_count[b] += 1                                 # b is trusted by someone
    for i in range(1, n + 1):
        if trust_count[i] == 0 and trusted_by_count[i] == n - 1:
            return i
    return -1

