public class Main {
    static int findJudge(int n, int[][] trust) {
        int[] trustCount = new int[n + 1];
        int[] trustedByCount = new int[n + 1];
        for (int[] t : trust) {
            trustCount[t[0]]++;                                        // a trusts someone
            trustedByCount[t[1]]++;                                       // b is trusted by someone
        }
        for (int i = 1; i <= n; i++) {
            if (trustCount[i] == 0 && trustedByCount[i] == n - 1) return i;
        }
        return -1;
    }
}

